app std-browse "2.5.0"
"std-browse as a Function — single primitive: data-grid. Owns the fetch + REFETCH (query/filter/page) state machine. Consumers configure fields/imageField/itemActions/cols/gap/variant; the atom renders the grid. Each `fields[]` entry accepts `{ name, label, variant }` plus optional `referenceEntity` + `displayField` to render a foreign-key column as the joined entity's display value (data-grid resolves @list[referenceEntity] at render time when both keys are present). `browseLook` (table default / dense / feed / gallery / master-detail / triage) selects one of six render bodies; dense/feed/gallery were folded in from std-browse-dense/-feed/-gallery (Phase 5.B); master-detail (split record view driven by the guarded VIEW/CLOSE self-transitions) and triage (inbox rows) were folded in 2026-07-26. Consumers retarget by setting browseLook."
type FieldSpec = { name : string!, label : string, variant : h3 | h4 | body | caption | badge | small | progress, icon : string, format : date | currency | number | boolean | percent, key : string, header : string }
type ItemAction = { label : string!, event : event, navigatesTo : string, variant : primary | secondary | ghost | danger, icon : string }
type ColumnSpec = { key : string!, field : string, header : string, width : string, align : left | center | right, className : string, weight : normal | medium | semibold, format : badge | date | currency | number | percent | boolean, icon : string }
type FilterSpec = { field : string!, label : string, options : [string] }
orbital BrowseItemOrbital {
  type BrowseDetailAction = {
    label : string!
    event : event!
    icon : string
    variant : string
  }

    type BrowseItemLoaded = Event { data : [BrowseItem], totalCount : number } "Fired when the BrowseItem collection finishes loading; payload.data holds the (possibly paginated) slice and totalCount holds the unsliced filter total. totalCount is optional so compiled-path emitters that haven't been migrated yet still validate"

    type BrowseItemLoadFailed = Event { error : string, code : string } "Fired when the BrowseItem collection fails to load"

  entity BrowseItem [runtime] {
    id : string!
    name : string! @description "The item's identifier or title." @synonyms "title, label, itemName"
    description : string @description "A textual explanation or summary of the item." @synonyms "summary, details, notes, explanation"
    status : "active" | "inactive" | "pending" @description "Indicates the current operational state of the item." @synonyms "state, condition, flag" = active
    createdAt : string
  }

  uses Typography from "std/behaviors/ui-typography"
  uses DataGrid from "std/behaviors/ui-data-grid"
  uses TableView from "std/behaviors/ui-table-view"
  uses DataList from "std/behaviors/ui-data-list"

  trait DataGrid1 = DataGrid.traits.DataGridRender -> BrowseItem {
    config {
      cols: @config.cols
      fields: @config.fields
      gap: @config.gap
      imageField: @config.imageField
      itemActions: @config.itemActions
      maxInlineActions: @config.maxInlineActions
      pageSize: @config.displayPageSize
      selfFetch: false
    }

    listens {
      BrowseItemBrowse.BrowseItemLoaded -> DataGridLoaded
    }
  }

  trait DenseTableView = TableView.traits.TableViewRender -> BrowseItem {
    config {
      columns: @config.columns
      emptyMessage: "No records"
      itemActions: @config.itemActions
      itemClickEvent: @config.itemClickEvent
      look: dense
      maxInlineActions: @config.maxInlineActions
      pageSize: @config.displayPageSize
      selectable: @config.selectable
      selfFetch: false
    }

    listens {
      BrowseItemBrowse.BrowseItemLoaded -> TableViewLoaded
    }
  }

  trait MasterListView = DataList.traits.DataListRender -> BrowseItem {
    config {
      fields: @config.fields
      itemActions: @config.itemActions
      itemClickEvent: @config.itemClickEvent
      maxInlineActions: @config.maxInlineActions
      variant: compact
      selfFetch: false
    }

    listens {
      BrowseItemBrowse.BrowseItemLoaded -> DataListLoaded
    }
  }

  trait BrowseItemBrowse -> @rebindable BrowseItem [interaction, collection] {
    initial: loading

    state loading {
      INIT -> loading
        (fetch BrowseItem {
          emit: { failure: BrowseItemLoadFailed, success: BrowseItemLoaded }
          filter: (and (or ["=", @config.scopeField, ""] ["=", (object/get @entity @config.scopeField), @user.id]) (or ["=", @config.initialFilterField, ""] ["=", (object/get @entity @config.initialFilterField), @config.initialFilterValue]))
          include: @config.include
          limit: @config.pageSize
          offset: 0
        })
        (render-ui main { rows: 4, type: skeleton })
      BrowseItemLoaded -> browsing
        (if ["=", @config.browseLook, dense]
          (render-ui main @config.denseBodyContent)
          (if ["=", @config.browseLook, feed]
            (render-ui main @config.feedBodyContent)
            (if ["=", @config.browseLook, gallery]
              (render-ui main @config.galleryBodyContent)
              (if ["=", @config.browseLook, master-detail]
                (render-ui main @config.masterDetailBodyContent)
                (if ["=", @config.browseLook, triage]
                  (render-ui main @config.triageBodyContent)
                  (render-ui main @config.bodyContent))))))
      BrowseItemLoadFailed -> error
        (render-ui main { message: ?error, title: "Couldn't load this list", type: alert, variant: error })
    }

    state browsing {
      ;; No skeleton repaint here, for the same reason REFETCH_* has none: from
      ;; a POPULATED body a skeleton unmounts the grid and flickers. First mount
      ;; is unaffected — `initial: loading` and `state loading`'s own INIT still
      ;; paint it; `browsing` is only reachable after a successful load.
      INIT -> loading
        (fetch BrowseItem {
          emit: { failure: BrowseItemLoadFailed, success: BrowseItemLoaded }
          filter: (and (or ["=", @config.scopeField, ""] ["=", (object/get @entity @config.scopeField), @user.id]) (or ["=", @config.initialFilterField, ""] ["=", (object/get @entity @config.initialFilterField), @config.initialFilterValue]))
          include: @config.include
          limit: @config.pageSize
          offset: 0
        })
      ;; REFETCH_* stays in `browsing` and DOES NOT replace the data-grid
      ;; with a spinner. Replacing during search-as-you-type unmounts the
      ;; grid every keystroke and causes a visible flicker. The fetch fires
      ;; in the background; when BrowseItemLoaded arrives we render the
      ;; grid with the new rows (handler below), so React reconciles the
      ;; data-grid in place instead of unmounting it.
      REFETCH_QUERY -> browsing
        (fetch BrowseItem {
          emit: { failure: BrowseItemLoadFailed, success: BrowseItemLoaded }
          filter: (and (or ["=", @config.scopeField, ""] ["=", (object/get @entity @config.scopeField), @user.id]) (or ["=", ?searchTerm, ""] (str/includes (object/get @entity name) ?searchTerm)))
          include: @config.include
          limit: @config.pageSize
          offset: 0
        })
      REFETCH_FILTER -> browsing
        (fetch BrowseItem {
          emit: { failure: BrowseItemLoadFailed, success: BrowseItemLoaded }
          filter: (and (or ["=", @config.scopeField, ""] ["=", (object/get @entity @config.scopeField), @user.id]) (or ["=", ?value, ""] ["=", (object/get @entity ?field), ?value]))
          include: @config.include
          limit: @config.pageSize
          offset: 0
        })
      REFETCH_PAGE -> browsing
        (fetch BrowseItem {
          emit: { failure: BrowseItemLoadFailed, success: BrowseItemLoaded }
          filter: (or ["=", @config.scopeField, ""] ["=", (object/get @entity @config.scopeField), @user.id])
          include: @config.include
          limit: @config.pageSize
          offset: ["*", ["-", ?page, 1], @config.pageSize]
        })
      ;; master-detail only: opening a row re-renders the split view with the
      ;; clicked row's detail (payload ?row feeds the panel). Guard keeps every
      ;; other look's machine untouched — VIEW still reaches external listeners
      ;; either way, and no effect here re-emits the trigger.
      VIEW -> browsing when ["=", @config.browseLook, "master-detail"]
        (render-ui main @config.masterDetailRecordBodyContent)
      CLOSE -> browsing when ["=", @config.browseLook, "master-detail"]
        (render-ui main @config.masterDetailBodyContent)
      BrowseItemLoaded -> browsing
        (if ["=", @config.browseLook, dense]
          (render-ui main @config.denseBodyContent)
          (if ["=", @config.browseLook, feed]
            (render-ui main @config.feedBodyContent)
            (if ["=", @config.browseLook, gallery]
              (render-ui main @config.galleryBodyContent)
              (if ["=", @config.browseLook, master-detail]
                (render-ui main @config.masterDetailBodyContent)
                (if ["=", @config.browseLook, triage]
                  (render-ui main @config.triageBodyContent)
                  (render-ui main @config.bodyContent))))))
    }

    state error {
      INIT -> loading
        (fetch BrowseItem {
          emit: { failure: BrowseItemLoadFailed, success: BrowseItemLoaded }
          filter: (and (or ["=", @config.scopeField, ""] ["=", (object/get @entity @config.scopeField), @user.id]) (or ["=", @config.initialFilterField, ""] ["=", (object/get @entity @config.initialFilterField), @config.initialFilterValue]))
          include: @config.include
          limit: @config.pageSize
          offset: 0
        })
        (render-ui main { rows: 4, type: skeleton })
    }

    emits {
      BrowseItemLoaded
        @description "Signals that a browse item has been successfully loaded."
        @synonyms "loaded, received, populated"
        @tier "domain"
      BrowseItemLoadFailed
        @description "Indicates a failure to load a browse item."
        @synonyms "error, failed, problem, unsuccessful"
        @tier "internal"
      VIEW -> external {
        id : string!
        row : BrowseItem!
      }
        @description "Signals a grid view has been displayed or updated."
        @synonyms "display, show, update, render"
        @tier "domain"
      EDIT -> external {
        id : string!
        row : BrowseItem!
      }
        @description "Signals a request to edit the selected item."
        @synonyms "modify, update, change"
        @tier "domain"
      DELETE -> external {
        id : string!
        row : BrowseItem!
      }
        @description "Signals a request to remove an item from the dataset."
        @synonyms "remove, discard, delete, purge"
        @tier "presentation"
    }

    listens {
      REFETCH_QUERY {
        searchTerm : string!
      }
        @description "Triggers a data refresh based on the current query."
        @synonyms "refresh, reload, update, re-query"
        @tier "domain"
      REFETCH_FILTER {
        entity : string!
        field : string!
        value : string!
        query : string
      }
        @description "Triggers a data refresh based on current filter criteria."
        @synonyms "refresh, filter, update, reload"
        @tier "domain"
      REFETCH_PAGE {
        page : number!
      }
        @description "Triggers a data grid page refresh."
        @synonyms "reload, refresh, update, paginate"
        @tier "domain"
      BrowseItemLoadFailed {
        error : string
        code : string
      }
        @description "Indicates a failure to load a browse item."
        @synonyms "error, failure, problem, unsuccessful"
        @tier "internal"
    }

    config {
      fields : [FieldSpec] = [{
        label: Name
        name: name
        variant: h4
      }, {
        label: Description
        name: description
        variant: caption
      }, {
        label: Status
        name: status
        variant: badge
      }]
        @label "Which fields should appear as columns?"
        @description "Each entry maps one entity field to a display column with an optional label and variant."
        @synonyms "visible columns, displayed fields, card fields, column list"
        @tier "presentation"
      columns : [ColumnSpec] = [{
        align: left
        field: name
        header: Name
        key: name
        weight: medium
      }, {
        align: left
        field: description
        header: Detail
        key: description
      }, {
        align: center
        field: status
        format: badge
        header: Status
        key: status
      }]
        @label "Table columns"
        @description "Column definitions for table-style variants (dense). Each maps an entity field to a column with optional width / align / weight / format."
        @tier "presentation"
      imageField : string = ""
        @label "Which field holds the row image?"
        @description "Entity field containing the thumbnail URL for each row."
        @synonyms "image field, thumbnail field, photo field, picture column"
        @tier "presentation"
      titleBinding : string = @item.name
        @label "Title field binding"
        @description "Binding path for the card title slot (e.g. @item.dishName)."
        @tier "internal"
      descriptionBinding : string = @item.description
        @label "Description field binding"
        @description "Binding path for the card body/subtitle slot."
        @tier "internal"
      badgeBinding : string = @item.status
        @label "Badge field binding"
        @description "Binding path for the status/badge slot."
        @tier "internal"
      imageLabelBinding : string = @item.thumbnailLabel
        @label "Image label binding"
        @description "Binding path for the image-area label slot."
        @tier "internal"
      priceBinding : string = @item.price
        @label "Price field binding"
        @description "Binding path for the price/amount overlay slot."
        @tier "internal"
      metaBinding : string = @item.createdAt
        @label "Meta field binding"
        @description "Binding path for the secondary meta slot (timestamp / category). Hosts binding a count or other non-date value should label it in the binding itself (e.g. (str/concat \"Vehicles: \" @item.vehicleCount)) and set metaFormat: none."
        @tier "internal"
      metaFormat : "none" | "date" | "time" | "datetime" | "number" = date
        @label "Meta value format"
        @description "Typography format for the feed meta slot — date by default so the createdAt binding renders human-readable instead of raw ISO; set none for non-date bindings."
        @tier "presentation"
      categoryBinding : string = @item.category
        @label "Category field binding"
        @description "Binding path for the category/tag slot."
        @tier "internal"
      priorityBinding : string = @item.priority
        @label "Priority field binding"
        @description "Binding path for the priority slot."
        @tier "internal"
      assigneeBinding : string = @item.assignee
        @label "Assignee field binding"
        @description "Binding path for the assignee/owner slot."
        @tier "internal"
      itemActions : [ItemAction] = []
        @label "What actions can users take on each row?"
        @description "Buttons rendered on each row (e.g. Edit, Delete, View)."
        @synonyms "row buttons, row actions, item actions, per-row buttons, table actions"
        @tier "presentation"
      cols : number = 1
        @label "How many columns in the grid?"
        @description "Number of columns in the responsive card/grid layout."
        @synonyms "columns, grid width, card columns, num columns"
        @tier "presentation"
      gap : string = md
        @label "Spacing between rows"
        @description "Gap between grid cells: sm, md, or lg."
        @synonyms "row gap, cell spacing, grid gap, padding between items"
        @tier "presentation"
      pageSize : number = 10
        @label "How many rows to fetch per page?"
        @description "Records fetched from the server per page request."
        @synonyms "fetch limit, records per page, batch size, page limit"
        @tier "presentation"
      displayPageSize : number = 10
        @label "How many rows to show at once?"
        @description "Rows visible per page before the pagination control appears."
        @synonyms "visible rows, items per page, display limit, show per page"
        @tier "presentation"
      include : [string] = []
        @label "Which relation fields to hydrate?"
        @description "Entity relation field names to hydrate on fetch (e.g. a `tag : Category` field named `tag`), so grid columns can use dot-paths like tag.name. Empty = no hydration, the default."
        @synonyms "relation hydration, populate relations, joined fields, hydrate relations"
        @tier "internal"
      filters : [FilterSpec] = []
        @label "Which filters should appear above the list?"
        @description "Dropdown filter facets by field, rendered as an embedded filter bar above the rows; each selection fires REFETCH_FILTER on this trait. Empty (the default) = no filter bar, which is the right setting whenever the page already composes std-filter beside this list and routes `XFilter.FILTER -> REFETCH_FILTER` — that is the wired owner and remains the primary path. Use this knob only for a standalone list with no page-level filter affordance, so the surface shows one filter bar instead of two."
        @synonyms "filter bar, faceted filters, field filters, column filters, dropdowns"
        @tier "presentation"
      maxInlineActions : number = 3
        @label "How many row actions to show before collapsing?"
        @description "Actions beyond this count collapse into a '⋯' overflow menu. Set 2–3 for dense tables."
        @synonyms "inline actions limit, overflow threshold, max buttons per row"
        @tier "presentation"
      itemClickEvent : event = VIEW
        @label "Which event does clicking a row fire?"
        @description "Row-click channel. Retarget when two browse lists coexist in one orbital and their VIEW payloads differ, so each gets its own typed channel."
        @synonyms "row click event, item click, open event, select event"
        @tier "presentation"
      scopeField : string = ""
        @label "Only show records owned by the signed-in user?"
        @description "Name the field on this entity that holds the viewer's id (e.g. memberId, patientId, assignee). When set, the list loads ONLY rows whose that field equals @user.id — the 'my bookings' / 'my appointments' shape. Left blank the list loads every row, which is the default. Declared, never inferred: guessing the column from its name would silently scope the wrong one."
        @synonyms "owner field, my records, only mine, only my own, scope to user, per-user list, mine only, owned by me"
        @tier "policy"
      initialFilterField : string = ""
        @label "Which field does the first load filter on?"
        @description "Name the field the INITIAL load filters on, paired with initialFilterValue. This is the detail half of a list-detail pair: a thread that must wait for a conversation to be picked sets the field to its parent key and leaves the value blank, so the first load matches nothing and the empty state shows instead of every record in the table. REFETCH_FILTER then supplies the real selection. Left blank the first load is unfiltered, which is the default."
        @synonyms "initial filter, first load filter, wait for selection, detail pane filter, requires selection, start empty"
        @tier "policy"
      initialFilterValue : string = ""
        @label "What value does the first load filter for?"
        @description "The value initialFilterField must equal on the first load. Blank is meaningful: it matches only records whose field is itself blank, which for a detail pane is normally none — that is how a thread stays empty until its parent is selected."
        @synonyms "initial filter value, first load value, default selection"
        @tier "policy"
      selectable : boolean = false
        @label "Show row selection checkboxes?"
        @description "Adds a checkbox column with select-all to the dense table. Enable only when the surface offers bulk actions — checkboxes with nothing to act on are a dead affordance."
        @synonyms "row checkboxes, multi-select, bulk select, selection column"
        @tier "presentation"
      bodySearch : boolean = true
        @label "Show the list's own search box?"
        @description "The dense/feed/gallery looks embed their own search box above the rows. Set false when the page already provides a search affordance (a toolbar Search molecule), so the surface shows one search box instead of two."
        @synonyms "inline search, list search, built-in search, show search, duplicate search"
        @tier "presentation"
      searchPlaceholder : string = "Search…"
        @label "Search box placeholder text"
        @description "Hint text inside the list search box (e.g. 'Search orders…')."
        @synonyms "search hint, placeholder, search box text, search label"
        @tier "presentation"
      filterBarLook : "toolbar" | "chips" | "pills" | "popover-trigger" | "inline-column-header" = toolbar
        @label "Filter bar look"
        @description "Visual treatment for the embedded filter bar, mirroring std-filter's own enum. Only applies when `filters` is non-empty."
        @synonyms "filter bar style, facet style, chips, pills"
        @tier "presentation"
      viewPattern : pattern = data-grid
        @label "Render pattern"
        @description "UI pattern used to render the collection. Used by the default bodyContent tree; Layer 3 variants override bodyContent directly instead and may ignore this knob."
        @tier "internal"
      browseLook : "table" | "dense" | "feed" | "gallery" | "master-detail" | "triage" = table
        @label "Browse look"
        @description "Layer 2 visual treatment for the whole browse surface. table = the default data-grid (bodyContent); dense = spreadsheet-style table with toolbar search (denseBodyContent); feed = chronological card stream (feedBodyContent); gallery = image-first responsive card grid (galleryBodyContent); master-detail = record-work split view — dense list left, clicked record's detail right (masterDetailBodyContent); triage = inbox-register compact rows for queue work (triageBodyContent). Selecting a non-table look swaps which body tree renders after rows load; any body may still be overridden directly at the call site for a one-off layout."
        @tier "presentation"
      detailFields : [string] = [name, description, status, createdAt]
        @label "Which fields appear in the master-detail record pane?"
        @description "Field names shown in the detail panel when browseLook = master-detail; the first entry doubles as the pane title. Consumers overriding columns/fields should override this list to match their entity."
        @synonyms "detail columns, record fields, detail pane fields"
        @tier "presentation"
      detailActions : [BrowseDetailAction] = [{ event: CLOSE, label: Close }]
        @label "Master-detail record pane actions"
        @description "Action buttons on the master-detail record pane (detail-panel `actions` descriptors: label/event/icon/variant). Consumers add their own record actions (Edit/Delete/…) alongside or instead of Close."
        @synonyms "record actions, detail actions, pane actions"
        @tier "presentation"
      bodyContent : render-ui = {
        children: [(if @config.bodySearch {
          children: [{
            className: "w-full max-w-md"
            clearable: true
            event: REFETCH_QUERY
            placeholder: @config.searchPlaceholder
            type: search-input
          }]
          direction: horizontal
          gap: sm
          type: stack
        } {
          children: []
          gap: none
          type: stack
        }), (if [">", (array/len @config.filters), 0] {
          children: [{
            entity: BrowseItem
            event: REFETCH_FILTER
            filters: @config.filters
            look: @config.filterBarLook
            type: filter-group
          }]
          direction: horizontal
          gap: sm
          type: stack
        } {
          children: []
          gap: none
          type: stack
        }), @trait.DataGrid1]
        direction: vertical
        gap: md
        type: stack
      }
        @label "Body content tree"
        @description "Render-ui SExpr rendered after rows load when browseLook = table (the default). Toolbar (search when bodySearch, filter bar when filters is non-empty) above the canonical data-grid call. Until 2026-08-27 this was the only one of the six looks with no search affordance at all. See denseBodyContent/feedBodyContent/galleryBodyContent for the other browseLook bodies; any may be overridden directly while inheriting the same trait, state machine, emits, and listens."
        @tier "internal"
      denseBodyContent : render-ui = {
        children: [(if @config.bodySearch {
          children: [{
            className: "w-full max-w-md"
            clearable: true
            event: REFETCH_QUERY
            placeholder: @config.searchPlaceholder
            type: search-input
          }]
          className: "px-card-md py-card-sm border-b border-[var(--color-border)]"
          direction: horizontal
          gap: sm
          type: stack
        } {
          children: []
          gap: none
          type: stack
        }), (if [">", (array/len @config.filters), 0] {
          children: [{
            entity: BrowseItem
            event: REFETCH_FILTER
            filters: @config.filters
            look: @config.filterBarLook
            type: filter-group
          }]
          className: "px-card-md py-card-sm border-b border-[var(--color-border)]"
          direction: horizontal
          gap: sm
          type: stack
        } {
          children: []
          gap: none
          type: stack
        }), {
          children: [@trait.DenseTableView]
          className: overflow-x-auto
          direction: vertical
          gap: none
          type: stack
        }]
        className: "rounded-lg border border-[var(--color-border)] bg-[var(--color-card)] shadow-sm overflow-hidden"
        direction: vertical
        gap: none
        type: stack
      }
        @label "Dense look body"
        @description "Render-ui SExpr rendered after rows load when browseLook = dense. Spreadsheet-style sticky-header data-table with a search bar; composes columns/itemActions/maxInlineActions/displayPageSize/searchPlaceholder. Folded from std-browse-dense (Phase 5.B)."
        @tier "internal"
      feedBodyContent : render-ui = {
        children: [(if @config.bodySearch {
          align: center
          children: [{
            className: w-full
            clearable: true
            event: REFETCH_QUERY
            placeholder: @config.searchPlaceholder
            type: search-input
          }]
          className: w-full
          direction: horizontal
          gap: sm
          type: stack
        } {
          children: []
          gap: none
          type: stack
        }), (if [">", (array/len @config.filters), 0] {
          children: [{
            entity: BrowseItem
            event: REFETCH_FILTER
            filters: @config.filters
            look: @config.filterBarLook
            type: filter-group
          }]
          className: w-full
          direction: horizontal
          gap: sm
          type: stack
        } {
          children: []
          gap: none
          type: stack
        }), {
          entity: ?data
          fields: []
          gap: md
          itemActions: @config.itemActions
          renderItem: (fn item {
            children: [{
              align: start
              children: [{
                className: "rounded-full flex-shrink-0"
                fallback: @config.titleBinding
                size: md
                type: avatar
              }, {
                children: [{
                  align: center
                  children: [{
                    className: truncate
                    content: @config.titleBinding
                    type: typography
                    variant: body
                    weight: medium
                  }, {
                    label: @config.categoryBinding
                    size: sm
                    type: badge
                    variant: neutral
                  }]
                  className: flex-wrap
                  direction: horizontal
                  gap: xs
                  type: stack
                }, {
                  className: "text-[var(--color-foreground)] whitespace-pre-wrap break-words leading-relaxed"
                  content: @config.descriptionBinding
                  type: typography
                  variant: body
                }, {
                  align: center
                  children: [{
                    color: muted
                    content: @config.metaBinding
                    format: @config.metaFormat
                    type: typography
                    variant: caption
                  }, {
                    label: @config.badgeBinding
                    size: sm
                    type: badge
                    variant: default
                  }]
                  className: pt-1
                  direction: horizontal
                  gap: sm
                  justify: between
                  type: stack
                }]
                className: "flex-1 min-w-0"
                direction: vertical
                gap: xs
                type: stack
              }]
